(4265442, 615126, 49109, '<td valign="top">Technicals: 0.5/2 - heavy noise, wrong white balance - to much green , slight tilt<br/>Composition: 0.5/2 - centered=boring<br/>Challenge Relation: 0.5/2 - people aren''t related to the library<br/>Originality/Creativity: 1/2 - intended motion blur<br/>Overall Impact: 0.5/2<br/>3</td>', 'Technicals: 0.5/2 - heavy noise, wrong white balance - to much green , slight tiltComposition: 0.5/2 - centered=boringChallenge Relation: 0.5/2 - people aren''t related to the libraryOriginality/Creativity: 1/2 - intended motion blurOverall Impact: 0.5/23', '2007-11-23 05:47:24.000000', NULL, 1),
(4265444, 614659, 49109, '<td valign="top">Technicals: 1/2 - wrong white balance - too much red/yellow; unpleasant shadows<br/> <br/>Composition: 1/2 - landscape orientation makes no sense, negative space is on wrong side; don''t understand his awkward pose<br/> <br/>Challenge Relation: 1/2 - with this pose and expression he doesn''t look smart at all<br/> <br/>Originality/Creativity: 1/2 <br/> <br/>Overall Impact: 1/2<br/> <br/>5</td>', 'Technicals: 1/2 - wrong white balance - too much red/yellow; unpleasant shadows Composition: 1/2 - landscape orientation makes no sense, negative space is on wrong side; don''t understand his awkward pose Challenge Relation: 1/2 - with this pose and expression he doesn''t look smart at all Originality/Creativity: 1/2  Overall Impact: 1/2 5', '2007-11-23 05:51:49.000000', NULL, 1),
